    internal static int NtPlainMarker(emon.Port.Cells wd, emon.Port.Cells et, int w, emon.Port.Cells mk) {
        // Is the whole word a plain note marker: one to three digits with at most a full stop or a parenthesis after them,
        // `[1]`, or a lone note symbol? Its characters go to `mk`; answers their count, 0 when it is not one.
        int tl = Lists.LsWl(wd, w);
        int i = 0;
        int nd = 0;
        if (tl < 1) {
            return 0;
        }
        int c0 = Lists.LsWc(wd, et, w, 0);
        if ((tl == 1) && ((c0 == 42) || ((c0 == 8224) || ((c0 == 8225) || ((c0 == 167) || (c0 == 182)))))) {
            emon.Port.CellsPush(mk, c0);
            return 1;
        }
        if ((tl >= 3) && (tl <= 5) && (c0 == 91) && (Lists.LsWc(wd, et, w, tl - 1) == 93)) {
            i = 1;
            while ((i < (tl - 1)) && (Lists.LsDigit(Lists.LsWc(wd, et, w, i)) >= 0)) {
                nd += 1;
                i += 1;
            }
            if ((nd == (tl - 2)) && (nd >= 1)) {
                i = 1;
                while (i < (tl - 1)) {
                    emon.Port.CellsPush(mk, 48 + Lists.LsDigit(Lists.LsWc(wd, et, w, i)));
                    i += 1;
                }
                return nd;
            }
            return 0;
        }
        while ((i < tl) && (i < 4) && (Lists.LsDigit(Lists.LsWc(wd, et, w, i)) >= 0)) {
            nd += 1;
            i += 1;
        }
        if ((nd < 1) || (nd > 3)) {
            return 0;
        }
        if ((i == (tl - 1)) && ((Lists.LsWc(wd, et, w, i) == 46) || (Lists.LsWc(wd, et, w, i) == 41))) {
            i = tl;
        }
        if (i != tl) {
            return 0;
        }
        i = 0;
        while (i < nd) {
            emon.Port.CellsPush(mk, 48 + Lists.LsDigit(Lists.LsWc(wd, et, w, i)));
            i += 1;
        }
        return nd;
    }
    internal static int NtScan(emon.Port.Cells wd, emon.Port.Cells ln, emon.Port.Cells et, emon.Port.Cells gl, emon.Port.Cells sf, emon.Port.Cells pages, emon.Port.Cells hc, emon.Port.Cells rf, emon.Port.Cells nb, emon.Port.Cells mk) {
