        int n = Evidence.LnCount(ln);
        int bsz = Style.StHget(sf, Style.SfhSize());
        int l = 0;
        int w = 0;
        int k = 0;
        int nrow = 0;
        int szok = 0;
        int band = 0;
        int sz0 = 0;
        int first = 0;
        int pwc = -1;
        int wl = 0;
        int @base = 0;
        int ml = 0;
        int ms = 0;
        emon.Port.CellsDrop(rf, 0);
        emon.Port.CellsDrop(nb, 0);
        emon.Port.CellsDrop(mk, 0);
        if (Style.StHget(sf, Style.SfhBody()) < 0) {
            return 0;
