        while (l < n) {
            if (Lists.LsUpright(ln, l) && (Heading.HdLevel(hc, l) == 0) && (Lists.LsGet(hc, l, Lists.LsKFlags()) == 0)) {
                sz0 = Lists.LsLineSize(sf, ln, l);
                @base = Lists.LsCap(Evidence.LnGet(ln, l, Evidence.LhBy0()));
                szok = 0;
                if ((bsz > 0) && ((sz0 * 100) <= (bsz * 96))) {
