                if ((pg >= 1) && (pg <= (emon.Port.CellsLen(pages) / 16))) {
                    if ((Lists.LsCap(Evidence.LnGet(ln, l, Evidence.LhY0())) * 2) >= Lists.LsCap(Model.PageH(pages, pg - 1))) {
                        band = 1;
