    internal static int NtLastWord(emon.Port.Cells wd, emon.Port.Cells ln, int l) {
        int w0 = Evidence.LnGet(ln, l, Evidence.LhFirst());
        int i = (w0 + Evidence.LnGet(ln, l, Evidence.LhCount())) - 1;
        while (i >= w0) {
            if (Lists.LsWl(wd, i) > 0) {
                return i;
            }
