        }
        while (i < wn) {
            int w = w0 + i;
            int tl = Lists.LsWl(wd, w);
            if (tl > 0) {
                if (first == 0) {
                    if ((k >= n) || (NtNh[off + k] != 32)) {
                        return 0;
