        int h = 0;
        int k = 0;
        while (r < nr) {
            if (emon.Port.CellsAt(rf, (r * NtRf) + 7) == 0) {
                if (fl < 0) {
                    fl = emon.Port.CellsAt(rf, (r * NtRf) + 3);
                }
                un += 1;
            }
            r += 1;
        }
        if ((un == 0) || (un > 400)) {
            return 0;
        }
        h = fl + 1;
        while (h < n) {
            if (Lists.LsUpright(ln, h) && (Heading.HdLevel(hc, h) > 0) && (NtNotesHeading(wd, ln, et, h) == 1)) {
                k = NtWalk(wd, et, ln, sf, hc, rf, mk, h, 0);
                if (k == un) {
                    NtWalk(wd, et, ln, sf, hc, rf, mk, h, 1);
                    r = 0;
                    while (r < nr) {
                        if (emon.Port.CellsAt(rf, (r * NtRf) + 7) == 0) {
                            emon.Port.CellsSet(rf, (r * NtRf) + 7, 2);
                        }
                        r += 1;
                    }
                    return k;
                }
            }
            h += 1;
        }
        return 0;
    }
    internal static int NtApplyBodies(emon.Port.Cells wd, emon.Port.Cells et, emon.Port.Cells gl, emon.Port.Cells ln, emon.Port.Cells nb, emon.Port.Cells mk, emon.Port.Cells rf, emon.Port.Cells hc) {
        // Rewrite the first word of every confirmed note body: its marker leaves the text, an `S_NOTE` group (the role: 4 a
        // footnote, 5 an endnote) takes its place. The line's row says a note starts there.
        int nn = emon.Port.CellsLen(nb) / NtNb;
        int i = 0;
        while (i < nn) {
            int b = i * NtNb;
            int st = emon.Port.CellsAt(nb, b + 7);
            if ((st == 1) || (st == 2)) {
                int l = emon.Port.CellsAt(nb, b);
                int w = emon.Port.CellsAt(nb, b + 2);
                int kind = emon.Port.CellsAt(nb, b + 3);
                int ts = Evidence.WdGet(wd, w, Evidence.HdTstart());
                int tl = Evidence.WdGet(wd, w, Evidence.HdTlen());
                int s = Lists.LsWrapBegin(et, Lists.LsSNote(), st + 3, -1);
                NtPutMark(et, mk, emon.Port.CellsAt(nb, b + 5), emon.Port.CellsAt(nb, b + 6));
                Lists.LsWrapEnd(et);
                if (kind == 1) {
                    int j = emon.Port.CellsAt(nb, b + 4);
                    while (j < (ts + tl)) {
                        emon.Port.CellsPush(et, emon.Port.CellsAt(et, j));
                        j += 1;
                    }
                }
                Lists.LsWrapSet(wd, et, w, s);
                Lists.LsPut(hc, l, Lists.LsKFlags(), Lists.LsFNote());
                // references in this very word are left alone
                int r = 0;
                while (r < (emon.Port.CellsLen(rf) / NtRf)) {
                    if (emon.Port.CellsAt(rf, r * NtRf) == w) {
                        emon.Port.CellsSet(rf, (r * NtRf) + 7, 9);
                    }
                    r += 1;
                }
            }
            i += 1;
        }
        return 0;
    }
    internal static int NtApplyRefs(emon.Port.Cells wd, emon.Port.Cells et, emon.Port.Cells gl, emon.Port.Cells rf, emon.Port.Cells mk) {
        // Rewrite every word that holds a confirmed reference: each reference becomes an `S_REF` group inside the word's
        // text, the marker as the group's text.
        int nr = emon.Port.CellsLen(rf) / NtRf;
        int i = 0;
        int i1 = 0;
        while (i < nr) {
            i1 = i + 1;
            while ((i1 < nr) && (emon.Port.CellsAt(rf, i1 * NtRf) == emon.Port.CellsAt(rf, i * NtRf))) {
                i1 += 1;
            }
            int w = emon.Port.CellsAt(rf, i * NtRf);
            int ts = Evidence.WdGet(wd, w, Evidence.HdTstart());
            int tl = Evidence.WdGet(wd, w, Evidence.HdTlen());
            int any = 0;
            int j = i;
            while (j < i1) {
                if ((emon.Port.CellsAt(rf, (j * NtRf) + 7) == 1) || (emon.Port.CellsAt(rf, (j * NtRf) + 7) == 2)) {
                    any = 1;
                }
                j += 1;
            }
            if (any == 1) {
                int s = emon.Port.CellsLen(et);
                int p = ts;
                j = i;
                while (j < i1) {
                    if ((emon.Port.CellsAt(rf, (j * NtRf) + 7) == 1) || (emon.Port.CellsAt(rf, (j * NtRf) + 7) == 2)) {
                        int a = emon.Port.CellsAt(rf, (j * NtRf) + 1);
                        int b = emon.Port.CellsAt(rf, (j * NtRf) + 2);
                        if ((a >= p) && (b <= (ts + tl)) && (b > a)) {
                            int q = p;
                            while (q < a) {
                                emon.Port.CellsPush(et, emon.Port.CellsAt(et, q));
                                q += 1;
                            }
                            Lists.LsWrapBegin(et, Lists.LsSRef(), 0, -1);
                            NtPutMark(et, mk, emon.Port.CellsAt(rf, (j * NtRf) + 5), emon.Port.CellsAt(rf, (j * NtRf) + 6));
                            Lists.LsWrapEnd(et);
                            p = b;
                        }
                    }
                    j += 1;
                }
                while (p < (ts + tl)) {
                    emon.Port.CellsPush(et, emon.Port.CellsAt(et, p));
                    p += 1;
                }
                Lists.LsWrapSet(wd, et, w, s);
            }
            i = i1;
        }
        return 0;
    }
    public static int NtAnalyze(emon.Port.Cells wd, emon.Port.Cells ln, emon.Port.Cells et, emon.Port.Cells gl, emon.Port.Cells sf, emon.Port.Cells sc, emon.Port.Cells pages, emon.Port.Cells hc, emon.Port.Cells rf, emon.Port.Cells nb, emon.Port.Cells mk) {
        // Find the captions, the note bodies and the references that point at them, and mark them (see the module's head).
        // `rf`, `nb`, `mk` are scratch. Answers the number of captions plus note bodies.
        if (Lists.LsOpen(hc) == 0) {
            return 0;
        }
        int n = Evidence.LnCount(ln);
        int l = 0;
        int nhl = -1;
        int found = 0;
        // captions first: a caption is never a note body. Found first (flag 8, nothing rewritten), then the candidates that
        // stand in a run (a list of figures: entries one under another, a line gap apart) are let go, then the rest rewritten.
        while (l < n) {
            if (Lists.LsUpright(ln, l) && (Heading.HdLevel(hc, l) == 0) && (Lists.LsGet(hc, l, Lists.LsKFlags()) == 0) && (NtCaption(wd, et, ln, sf, sc, hc, l, 0) == 1)) {
                Lists.LsPut(hc, l, Lists.LsKFlags(), Lists.LsFCap());
            }
            l += 1;
        }
        l = 0;
        while (l < n) {
            if (Lists.LsGet(hc, l, Lists.LsKFlags()) == Lists.LsFCap()) {
                if ((NtInRun(sf, ln, hc, l) == 1) || (NtTocLike(wd, ln, et, sf, l) == 1)) {
                    Lists.LsPut(hc, l, Lists.LsKFlags(), 64);
                }
            }
            l += 1;
        }
        l = 0;
        while (l < n) {
            int fl = Lists.LsGet(hc, l, Lists.LsKFlags());
            if ((fl == Lists.LsFCap()) || (fl == 64)) {
                Lists.LsPut(hc, l, Lists.LsKFlags(), 0);
                if (fl == Lists.LsFCap()) {
                    found += NtCaption(wd, et, ln, sf, sc, hc, l, 1);
                }
            }
            l += 1;
        }
        NtScan(wd, ln, et, gl, sf, pages, hc, rf, nb, mk);
        nhl = NtFirstNotesHeading(wd, ln, et, hc, rf);
        NtMatch(rf, nb, mk, nhl);
        NtMarkerless(wd, et, ln, sf, hc, rf, mk);
        l = 0;
        while (l < (emon.Port.CellsLen(nb) / NtNb)) {
            if ((emon.Port.CellsAt(nb, (l * NtNb) + 7) == 1) || (emon.Port.CellsAt(nb, (l * NtNb) + 7) == 2)) {
                found += 1;
            }
            l += 1;
        }
        NtApplyBodies(wd, et, gl, ln, nb, mk, rf, hc);
        NtApplyRefs(wd, et, gl, rf, mk);
        return found;
    }
}
